mapper.select:
SELECT g.guestbook_id, g.writer_id, u.nickname AS writer_nickname, g.content, g.is_secret, g.created_at, g.updated_at FROM guestbook g JOIN minihompy m ON m.minihompy_id = g.minihompy_id JOIN users u ON u.user_id = g.writer_id WHERE m.user_id = #{ownerId} AND g.deleted_at IS NULL
AND g.guestbook_id < #{cursor}
ORDER BY g.guestbook_id DESC LIMIT #{size}
